INSERT INTO system.translations (key, language, value, created_at, created_by, updated_at, updated_by, version) VALUES ('system.entities.user_profile.hints.is_admin', 'de-DE', 'Das Kennzeichen des Identitätsadministrators ermöglicht dem Benutzer den Zugriff auf das IDP-System, um Änderungen auf administrativer Ebene vorzunehmen, gewährt jedoch keine Verwaltungsrechte für diese Anwendung. Um Administrationszugriffe auf die Anwendung zu gewähren, legen Sie die Anwendungsrollen fest.', '2026-05-18T14:27:00Z', 'initial-setup', '2026-05-18T14:27:00Z', 'initial-setup', 1) ON CONFLICT (key, language) WHERE deleted_at IS NULL DO NOTHING;
INSERT INTO system.translations (key, language, value, created_at, created_by, updated_at, updated_by, version) VALUES ('system.entities.user_profile.hints.is_admin_title', 'de-DE', 'Keine Administratorrolle', '2026-05-18T14:27:00Z', 'initial-setup', '2026-05-18T14:27:00Z', 'initial-setup', 1) ON CONFLICT (key, language) WHERE deleted_at IS NULL DO NOTHING;
INSERT INTO system.translations (key, language, value, created_at, created_by, updated_at, updated_by, version) VALUES ('system.entities.user_profile.hints.is_verified', 'de-DE', 'Gibt an, ob der Identitätsverifikationsprozess erfolgreich abgeschlossen wurde. Er kann von einem KYC-Prozess oder einer anderen Art der Verifikation abhängen.', '2026-05-18T14:27:00Z', 'initial-setup', '2026-05-18T14:27:00Z', 'initial-setup', 1) ON CONFLICT (key, language) WHERE deleted_at IS NULL DO NOTHING;
INSERT INTO system.translations (key, language, value, created_at, created_by, updated_at, updated_by, version) VALUES ('system.entities.user_profile.hints.is_verified_title', 'de-DE', 'Identitätsverifikation', '2026-05-18T14:27:00Z', 'initial-setup', '2026-05-18T14:27:00Z', 'initial-setup', 1) ON CONFLICT (key, language) WHERE deleted_at IS NULL DO NOTHING;
INSERT INTO system.translations (key, language, value, created_at, created_by, updated_at, updated_by, version) VALUES ('system.entities.user_profile.hints.email_verified', 'de-DE', 'Gibt an, ob die E-Mail verifiziert wurde, in der Regel über einen Link, der an den Posteingang gesendet wird, der vermutlich nur vom Benutzer gelesen werden kann, dessen Profil wir konfigurieren.', '2026-05-18T14:27:00Z', 'initial-setup', '2026-05-18T14:27:00Z', 'initial-setup', 1) ON CONFLICT (key, language) WHERE deleted_at IS NULL DO NOTHING;
